    annotationHorizontalLine: {
      yValue: 70,
      text: 'Ligne de référence',
    },
    annotationArea: {
      selector: {
        field: 'month',
        operator: 'in',
        value: ['2025-07', '2025-08'],
      },
      text: 'Phase de hausse',
    },
    annotationDifferenceLine: [
      {
        start: {
          selector: [
            {
              field: 'month',
              operator: 'in',
              value: ['2025-07'],
            },
            {
              field: 'net_profit_million',
              operator: '=',
              value: 62.61,
            },
          ],
        },
        end: {
          selector: [
            {
              field: 'month',
              operator: 'in',
              value: ['2025-12'],
            },
          ],
        },
        differenceType: 'absolute',
      },
    ],
    yAxis: {
      autoFormat: false,
      numFormat: {
        type: 'number',
        fractionDigits: 2,
        suffix: ' millions de yuans',
      },
    },
    theme: 'swiss-modern',
  }

  const parseRes = zVSeed.safeParse(vseed)
  if (parseRes.success) {
    console.log('zVSeed parse success!!!')
